/**
 * @param {number} cost1
 * @param {number} cost2
 * @param {number} costBoth
 * @param {number} need1
 * @param {number} need2
 * @return {number}
 */
var minimumCost = function(cost1, cost2, costBoth, need1, need2) {
    const totalIndividual = cost1 * need1 + cost2 * need2;

    const totalBoth = costBoth * Math.max(need1, need2);

    const totalSplit = costBoth * Math.min(need1, need2) + (
        need1 < need2 ? (need2 - need1) * cost2 : (need1 - need2) * cost1
    );

    return Math.min(
        totalIndividual,
        totalBoth,
        totalSplit,
    );
};

/**
 * @param {number} cost1
 * @param {number} cost2
 * @param {number} costBoth
 * @param {number} need1
 * @param {number} need2
 * @return {number}
 */
var minimumCost = function(cost1, cost2, costBoth, need1, need2) {
    const totalIndividual = cost1 * need1 + cost2 * need2;

    if (cost1 + cost2 < costBoth) {
        return totalIndividual;
    }

    let minNeed, maxNeed, added;

    if (need1 < need2) {
        minNeed = need1;
        maxNeed = need2;
        added = (need2 - need1) * cost2;
    } else {
        minNeed = need2;
        maxNeed = need1;
        added = (need1 - need2) * cost1;
    }

    return Math.min(costBoth * maxNeed, costBoth * minNeed + added);
};

/**
 * @param {number} cost1
 * @param {number} cost2
 * @param {number} costBoth
 * @param {number} need1
 * @param {number} need2
 * @return {number}
 */
var minimumCost = function(cost1, cost2, costBoth, need1, need2) {
    if (cost1 + cost2 < costBoth) {
        return cost1 * need1 + cost2 * need2;
    }
    if (need1 < need2) {
        return Math.min(costBoth * need2, costBoth * need1 + (need2 - need1) * cost2);
    }
    return Math.min(costBoth * need1, costBoth * need2 + (need1 - need2) * cost1);
};
